def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.abs(remaining - 0.5))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target_fill = 0.85
    remaining = bins - item
    post_fill = 1.0 - (remaining / bins)
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.square(post_fill - target_fill))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = item / bins
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.abs(utilization - 0.75) - np.exp(-remaining))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    ratio = item / bins
    return np.where((bins < item) | (bins <= 0), -np.inf, -np.abs(0.5 - ratio))
